const text = input.response || input.text || '';
const match = text.match(/RISK_LEVEL:\s*(low|medium|high)/i);
const level = match ? match[1].toLowerCase() : 'medium';
const scoreMap = { low: 20, medium: 55, high: 85 };
const riskScore = scoreMap[level];
return { ...input, riskLevel: level, riskScore, isHighRisk: riskScore >= 80 };
